struct caps_filter
{
    BOOLEAN buttons;
    BOOLEAN values;
    BOOLEAN array;
    DWORD   usage_page;
    USHORT  collection;
    DWORD   usage;
    UCHAR   report_id;
};

struct usage_value_params
{
    BOOL array;
    USAGE usage;
    void *value_buf;
    USHORT value_len;
    void *report_buf;
};
